/* General Styles */
body {
    font-family: Arial, sans-serif;
    background-color: #f4f4f4;
    color: #333;
    margin: 0;
    padding: 0;
}

.app-shell {
    display: flex;
    flex-direction: column;
    height: 100vh;
}

.app-header {
    background-color: #2c3e50;
    color: white;
    padding: 15px;
    text-align: center;
}

.workspace-grid {
    display: grid;
    grid-template-columns: 1fr 3fr;
    grid-template-rows: auto 1fr;
    gap: 10px;
    padding: 10px;
    flex-grow: 1;
}

.intake-panel {
    background-color: #ecf0f1;
    padding: 15px;
    border-radius: 5px;
}

.filters-panel {
    background-color: #bdc3c7;
    padding: 15px;
    border-radius: 5px;
}

.results-panel {
    background-color: #ffffff;
    padding: 15px;
    border-radius: 5px;
    overflow-y: auto;
}

.manual-panel {
    background-color: #ecf0f1;
    padding: 15px;
    border-radius: 5px;
}

.status-strip {
    background-color: #e74c3c;
    color: white;
    padding: 10px;
    text-align: center;
}

.action-bar {
    display: flex;
    justify-content: space-between;
    padding: 10px;
}

/* Result Card Styles */
.highlight-card {
    background-color: #ffffff;
    border: 1px solid #bdc3c7;
    border-radius: 5px;
    padding: 10px;
    margin-bottom: 10px;
}

.highlight-title {
    font-size: 1.2em;
    font-weight: bold;
    margin-bottom: 5px;
}

.score-badge {
    background-color: #27ae60;
    color: white;
    padding: 5px 10px;
    border-radius: 3px;
    font-weight: bold;
}

.metadata-row {
    display: flex;
    justify-content: space-between;
    margin: 5px 0;
}

.metadata-streamer,
.metadata-game,
.metadata-time,
.metadata-category {
    font-size: 0.9em;
    color: #7f8c8d;
}

.highlight-description {
    font-size: 0.9em;
    color: #34495e;
}

/* Responsive Styles */
@media (max-width: 768px) {
    .workspace-grid {
        grid-template-columns: 1fr;
    }

    .action-bar {
        flex-direction: column;
        align-items: flex-start;
    }
}

export function scoreRecord(record) {
    const intensityBoost = record.intensity * 2; // Example boost factor
    const chatRateBoost = record.chatRate * 1.5; // Example boost factor
    const keywordBoost = record.keywords.length * 3; // Example boost for each keyword
    const categoryBoost = record.category === 'high' ? 10 : 0; // Example boost for category
    const titleDescriptionBoost = (record.title.length + record.description.length) * 0.5; // Example boost for title and description length

    const score = intensityBoost + chatRateBoost + keywordBoost + categoryBoost + titleDescriptionBoost;

    return {
        ...record,
        score: score
    };
}

export function sortRecords(records) {
    return records.sort((a, b) => b.score - a.score);
}

export function applyFilters(records, filters) {
  const { streamer, game, category, minScore } = filters;

  return records.filter(record => {
    const matchesStreamer = !streamer || String(record.streamer || '').toLowerCase().includes(streamer.toLowerCase());
    const matchesGame = !game || String(record.game || '').toLowerCase().includes(game.toLowerCase());
    const matchesCategory = !category || String(record.category || '').toLowerCase().includes(category.toLowerCase());
    const matchesScore = minScore === undefined || record.score >= minScore;

    return matchesStreamer && matchesGame && matchesCategory && matchesScore;
  });
}

export function parseRecordsFromText(text) {
  const parsed = JSON.parse(text);

  if (Array.isArray(parsed)) {
    return parsed;
  }

  return importData(parsed);
}

export function normalizeRecord(record, index) {
  return {
    sourceId: record.sourceId,
    sourceType: record.sourceType,
    viewerSpike: record.viewerSpike,
    clipSignal: record.clipSignal,
    confidence: record.confidence,
    moderationFlag: record.moderationFlag,
    streamer: record.streamer,
    game: record.game,
    category: record.category,
    timestamp: record.timestamp || record.time,
    title: record.title,
    description: record.description,
    intensity: record.intensity,
    chatRate: record.chatRate,
    keywords: record.keywords,
    index: index // Include index for reference
  };
}

export function importData(input) {
  let records = [];

  if (Array.isArray(input)) {
    records = input;
  } else if (typeof input === 'string') {
    records = JSON.parse(input);
  } else if (typeof input === 'object') {
    records = input.records || input.events || input.highlights || input.items || input.payload?.records || [];
  }

  return records.map(normalizeRecord);
}

export function downloadJson(filename, records) {
  const blob = new Blob([JSON.stringify(records, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);

  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);

  URL.revokeObjectURL(url);
}

export function exportData(records, filename = 'highlight-clips.json') {
  downloadJson(filename, records);
}

const LOCAL_STORAGE_KEY = 'cgnk.streamerHighlightFinder.records';

export function loadRecords() {
  return loadFromLocalStorage();
}

export function saveRecords(records) {
  return saveToLocalStorage(records);
}

export function clearRecords() {
  localStorage.removeItem(LOCAL_STORAGE_KEY);
}

export function loadFromLocalStorage() {
  const records = localStorage.getItem(LOCAL_STORAGE_KEY);
  return records ? JSON.parse(records) : [];
}

export function saveToLocalStorage(records) {
  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(records));
}

export function renderRecords(records, container) {
    container.innerHTML = ''; // Clear previous content

    records.forEach(record => {
        const card = document.createElement('div');
        card.className = 'highlight-card';

        const title = document.createElement('h3');
        title.className = 'highlight-title';
        title.textContent = record.title || 'Untitled Highlight';
        card.appendChild(title);

        const scoreBadge = document.createElement('span');
        scoreBadge.className = 'score-badge';
        scoreBadge.textContent = `Score: ${record.score}`;
        card.appendChild(scoreBadge);

        const metadataRowStreamer = document.createElement('p');
        metadataRowStreamer.className = 'metadata-row metadata-streamer';
        metadataRowStreamer.textContent = `Streamer: ${record.streamer}`;
        card.appendChild(metadataRowStreamer);

        const metadataRowGame = document.createElement('p');
        metadataRowGame.className = 'metadata-row metadata-game';
        metadataRowGame.textContent = `Game: ${record.game}`;
        card.appendChild(metadataRowGame);

        const metadataRowTime = document.createElement('p');
        metadataRowTime.className = 'metadata-row metadata-time';
        metadataRowTime.textContent = `Time: ${record.timestamp}`;
        card.appendChild(metadataRowTime);

        const metadataRowCategory = document.createElement('p');
        metadataRowCategory.className = 'metadata-row metadata-category';
        metadataRowCategory.textContent = `Category: ${record.category}`;
        card.appendChild(metadataRowCategory);

        const description = document.createElement('p');
        description.className = 'highlight-description';
        description.textContent = record.description || 'No description available.';
        card.appendChild(description);

        // Highlight keywords if present
        if (record.keywords && record.keywords.length > 0) {
            const keywords = document.createElement('p');
            keywords.className = 'highlight-keywords';
            keywords.textContent = `Keywords: ${record.keywords.join(', ')}`;
            card.appendChild(keywords);
        }

        container.appendChild(card);
    });
}

export function renderSummary(records, filteredRecords, summaryElement) {
    const totalRecords = records.length;
    const filteredCount = filteredRecords.length;

    summaryElement.textContent = `Total Records: ${totalRecords}, Filtered Records: ${filteredCount}`;
}

export function renderError(message, container) {
    const errorElement = document.createElement('div');
    errorElement.className = 'error-message';
    errorElement.textContent = message;
    container.appendChild(errorElement);
}

export function readFilters(dom) {
  const streamer = dom.querySelector('#filterStreamer').value;
  const game = dom.querySelector('#filterGame').value;
  const category = dom.querySelector('#filterCategory').value;
  const minScore = parseFloat(dom.querySelector('#filterScore').value) || 0;

  return { streamer, game, category, minScore };
}

export function readManualMarker(form) {
  const streamer = form.querySelector('#streamer').value;
  const game = form.querySelector('#game').value;
  const category = form.querySelector('#category').value;
  const timestamp = form.querySelector('#timestamp').value;
  const time = form.querySelector('#time').value;
  const intensity = parseFloat(form.querySelector('#intensity').value) || 0;
  const chatRate = parseFloat(form.querySelector('#chatRate').value) || 0;
  const keywords = form.querySelector('#keywords').value.split(',').map(k => k.trim());
  const title = form.querySelector('#title').value;
  const description = form.querySelector('#description').value;

  return { streamer, game, category, timestamp, time, intensity, chatRate, keywords, title, description };
}

export function bindDom(dom, handlers) {
  const importButton = dom.querySelector('#import-button');
  const exportButton = dom.querySelector('#export-button');
  const filterForm = dom.querySelector('#filter-form');
  const manualForm = dom.querySelector('#manual-form');

  importButton.addEventListener('click', handlers.import);
  exportButton.addEventListener('click', handlers.export);
  filterForm.addEventListener('submit', handlers.applyFilters);
  manualForm.addEventListener('submit', handlers.submitManualMarker);
}

export function setupForms(domIds) {
  domIds.forEach(id => {
    const form = document.getElementById(id);
    if (form) {
      form.reset();
    }
  });
}

// app.js
import { scoreRecord, sortRecords } from './core/scoring.js';
import { applyFilters } from './core/filtering.js';
import { parseRecordsFromText, normalizeRecord, importData } from './core/importer.js';
import { downloadJson, exportData } from './core/exporter.js';
import { loadRecords, saveRecords, clearRecords, loadFromLocalStorage, saveToLocalStorage } from './state/store.js';
import { renderRecords, renderSummary, renderError } from './ui/render.js';
import { readFilters, readManualMarker } from './ui/forms.js';

const statusSummary = document.getElementById('status-summary');
const recordsContainer = document.getElementById('records-container');
const fileInput = document.getElementById('file-input');
const jsonTextarea = document.getElementById('json-textarea');
const importButton = document.getElementById('import-button');
const filterForm = document.getElementById('filter-form');
const exportButton = document.getElementById('export-button');

// Load records from local storage on startup
let records = loadFromLocalStorage() || [];
let filteredRecords = [];

// Render initial records
renderRecords(records, recordsContainer);
renderSummary(records, filteredRecords, statusSummary);

// Handle file input for importing records
fileInput.addEventListener('change', (event) => {
    const file = event.target.files[0];
    if (file) {
        importData(file)
            .then(newRecords => {
                records.push(...newRecords.map(normalizeRecord).map(scoreRecord));
                saveRecords(records);
                renderRecords(records, recordsContainer);
                renderSummary(records, filteredRecords, statusSummary);
            })
            .catch(error => renderError(error.message, recordsContainer));
    }
});

// Handle JSON textarea import
importButton.addEventListener('click', () => {
    const text = jsonTextarea.value;
    const newRecords = parseRecordsFromText(text);
    records.push(...newRecords.map(normalizeRecord).map(scoreRecord));
    saveRecords(records);
    renderRecords(records, recordsContainer);
    renderSummary(records, filteredRecords, statusSummary);
});

// Handle filter form submission
filterForm.addEventListener('submit', (event) => {
    event.preventDefault();
    const filters = readFilters(filterForm);
    filteredRecords = applyFilters(records, filters);
    renderRecords(filteredRecords, recordsContainer);
    renderSummary(records, filteredRecords, statusSummary);
});

// Handle manual marker submission
const manualForm = document.getElementById('manual-form');
manualForm.addEventListener('submit', (event) => {
    event.preventDefault();
    const newRecord = readManualMarker(manualForm);
    records.push(scoreRecord(newRecord));
    saveRecords(records);
    renderRecords(records, recordsContainer);
    renderSummary(records, filteredRecords, statusSummary);
});

// Handle export button click
exportButton.addEventListener('click', () => {
    downloadJson('filtered_highlights.json', filteredRecords);
});

// Save records to local storage on unload
window.addEventListener('beforeunload', () => {
    saveToLocalStorage(records);
});

window.runSmokeTest = async function() {
  const recordsContainer = document.getElementById('records-container');
  const jsonTextarea = document.getElementById('json-textarea');
  const importButton = document.getElementById('import-button');
  const filterForm = document.getElementById('filter-form');
  const manualForm = document.getElementById('manual-form');
  const exportButton = document.getElementById('export-button');

  jsonTextarea.value = JSON.stringify([
    {
      streamer: "TestStreamer",
      game: "TestGame",
      timestamp: "2023-10-01T12:00:00Z",
      category: "TestCategory",
      intensity: 5,
      chatRate: 10,
      keywords: ["test", "highlight"],
      title: "Test Highlight",
      description: "This is a test highlight.",
      score: 0
    }
  ]);

  importButton.click();

  await new Promise(resolve => setTimeout(resolve, 1000));

  const scoreBadges = recordsContainer.querySelectorAll('.score-badge');
  scoreBadges.forEach(badge => {
    const score = parseInt(badge.textContent.match(/\d+/)[0], 10);
    if (isNaN(score) || score <= 0) {
      throw new Error('Score is not numeric or positive');
    }
  });

  const cards = recordsContainer.querySelectorAll('.highlight-card');
  const sortedScores = Array.from(scoreBadges).map(badge => parseInt(badge.textContent.match(/\d+/)[0], 10)).sort((a, b) => b - a);
  const visibleScores = Array.from(scoreBadges).map(badge => parseInt(badge.textContent.match(/\d+/)[0], 10));

  if (JSON.stringify(visibleScores) !== JSON.stringify(sortedScores)) {
    throw new Error('Visible cards are not sorted descending by score');
  }

  const filterStreamer = document.getElementById('filterStreamer');
  const filterGame = document.getElementById('filterGame');
  const filterCategory = document.getElementById('filterCategory');
  const filterScore = document.getElementById('filterScore');

  filterStreamer.value = "TestStreamer";
  filterGame.value = "TestGame";
  filterCategory.value = "TestCategory";
  filterScore.value = "5";

  filterForm.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));

  await new Promise(resolve => setTimeout(resolve, 1000));

  filterStreamer.value = '';
  filterGame.value = '';
  filterCategory.value = '';
  filterScore.value = '';

  filterForm.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));

  const manualTitleInput = manualForm.querySelector('[name="title"]');
  const manualStreamerInput = manualForm.querySelector('[name="streamer"]');
  const manualDescriptionInput = manualForm.querySelector('[name="description"]');

  manualTitleInput.value = "New Highlight";
  manualStreamerInput.value = "TestStreamer";
  manualDescriptionInput.value = "This is a new highlight.";

  manualForm.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));

  await new Promise(resolve => setTimeout(resolve, 1000));

  if (!localStorage.getItem('cgnk.streamerHighlightFinder.records').includes("New Highlight")) {
    throw new Error('New record not found in localStorage');
  }

  const visibleCardsAfterManual = recordsContainer.querySelectorAll('.highlight-card');
  const titles = Array.from(visibleCardsAfterManual).map(card => card.querySelector('.highlight-title').textContent);
  if (!titles.includes("New Highlight")) {
    throw new Error('New title not found in visible results');
  }

  const descriptions = Array.from(visibleCardsAfterManual).map(card => card.querySelector('.highlight-description').textContent);
  if (!descriptions.includes("This is a new highlight.")) {
    throw new Error('New description not found in visible results');
  }

  const exportSpy = jest.spyOn(URL, 'createObjectURL');
  exportButton.click();
  if (!exportSpy.mock.calls.length) {
    throw new Error('Export action was not triggered');
  }

  return { status: 'pass' };
};

window.runIndustrialIOSmokeTest = async function() {
  const responseBundle = await fetch('data/industrial_input_bundle.json');
  const industrialBundle = await responseBundle.json();

  const responseExpected = await fetch('data/expected_outputs.json');
  const expectedOutputs = await responseExpected.json();

  const jsonTextarea = document.getElementById('json-textarea');
  jsonTextarea.value = JSON.stringify(industrialBundle);

  const importButton = document.getElementById('import-button');
  importButton.dispatchEvent(new Event('click', { bubbles: true, cancelable: true }));

  const importedCount = localStorage.getItem('cgnk.streamerHighlightFinder.records') ? JSON.parse(localStorage.getItem('cgnk.streamerHighlightFinder.records')).length : 0;
  const visibleCards = document.querySelectorAll('.highlight-card');
  const visibleCount = visibleCards.length;

  const scores = Array.from(visibleCards).map(card => {
    const scoreText = card.querySelector('.score-badge').textContent;
    return parseFloat(scoreText.match(/[\d.]+/)[0]);
  }).sort((a, b) => b - a);

  const topRankedTitles = expectedOutputs.ranked_highlights.map(output => output.title);
  const hasTopRankedTitle = topRankedTitles.some(title => Array.from(visibleCards).some(card => card.querySelector('.highlight-title').textContent.includes(title)));

  const sourceIds = new Set(JSON.parse(localStorage.getItem('cgnk.streamerHighlightFinder.records')).map(record => record.sourceId));
  const hasThreeSourceIds = sourceIds.size >= 3;

  const exportButton = document.getElementById('export-button');
  exportButton.dispatchEvent(new Event('click', { bubbles: true, cancelable: true }));

  const blobTriggered = !!(window.Blob || window.URL.createObjectURL);

  if (importedCount < 20) throw new Error('Less than 20 records imported.');
  if (!scores.every((score, index) => index === 0 || score <= scores[index - 1])) throw new Error('Scores are not in descending order.');
  if (!hasTopRankedTitle) throw new Error('No expected top ranked title found.');
  if (!hasThreeSourceIds) throw new Error('Less than 3 source IDs found in storage.');
  if (!blobTriggered) throw new Error('Export did not trigger Blob or URL.createObjectURL.');

  return { status: 'pass', importedCount, visibleCount, checkedOutputs: expectedOutputs };
};
